// Specification-only: inductive definition over natural numbers.
pub fn triangle(n: usize) -> usize {
    // triangle(0) = 0; triangle(n+1) = triangle(n) + (n+1)
    let mut acc: usize = 0;
    let mut k: usize = 1;
    while k <= n {
        acc += k;
        k += 1;
    }
    acc
}

// Proof-like helper: establishes monotonicity by a straightforward argument.
// In standard Rust we cannot encode/verify proofs, so we provide a total
// function that panics if the claimed property is violated.
pub fn triangle_is_monotonic(i: usize, j: usize) {
    assert!(i <= j);
    let ti = triangle(i);
    let tj = triangle(j);
    assert!(ti <= tj);
}

// Tail-recursive procedure that advances idx toward n, maintaining `*sum` as
// triangle(idx), and finishing with `*sum == triangle(n)`.
//
// Assumptions (as described in the problem statement):
// - idx <= n
// - *sum == triangle(idx)
// - triangle(n) fits in u32, so intermediate additions do not overflow.
pub fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    fn go(n: u32, idx: u32, sum: &mut u32) {
        if idx == n {
            return;
        }
        // Next index is idx + 1 (safe because idx < n implies idx + 1 <= n <= u32::MAX)
        let next = idx + 1;
        // Update accumulator: triangle(next) = triangle(idx) + next
        *sum = sum.wrapping_add(next); // safe under the stated no-overflow assumption
        go(n, next, sum);
    }

    debug_assert!(idx <= n);
    go(n, idx, sum);
}

